434	async function provision(job: Job) {
435	  const server = await loadServer(job);
436	  // Clear any stale failure reason from a previous attempt as this run starts, so
437	  // a successful retry doesn't leave the last error hanging around on the row.
438	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null, provisioningStep: null } });
439	  // Best-effort, human-readable "what's happening right now" label for
440	  // <ProvisioningOverlay/> (lib/provisioning-step.ts) — written between the real,
441	  // observable checkpoints below (Proxmox clone/config/start, guest-agent boot,
442	  // SSH reachability, and the game's own port opening). Never allowed to fail
443	  // the provision — it's purely a display aid, same discipline as worker/hosting.ts's
444	  // equivalent `step()`.
445	  const step = (label: string) =>
446	    db.server.update({ where: { id: server.id }, data: { provisioningStep: label } }).catch(() => undefined);
447	
448	  if (SANDBOX) {
449	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
450	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
451	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
452	    const password = generatePassword();
453	    const ip = sandboxIp(vmid);
454	    await db.server.update({
455	      where: { id: server.id },
456	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
457	    });
458	    await notify(
459	      server.userId,

600	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
601	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
602	  };
603	  if (dedicated) {
604	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
605	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
606	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
607	  } else {
608	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
609	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
610	  }
611	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
612	
613	  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
614	  // customer bought as a deploy-time upsell, so the VM is born the right size and
615	  // no separate DISK_EXPAND job is needed on a fresh order.
616	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
617	    disk: "scsi0",
618	    size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
619	  });
620	
621	  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
622	  // for a NAT server. If it cannot be proved, the readiness message says so
623	  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
624	  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
625	  // its IP, which is a worse outcome than a missing forward.
626	  let natError: Error | null = null;
627	  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);
628	
629	  // Idempotent start. A worker restart (e.g. a deploy) can interrupt a provision
630	  // AFTER the VM was already created and started; the reaper then re-queues the job.
631	  // Starting an already-running VM makes Proxmox's start task fail with "already
632	  // running", which — before this guard — stranded a perfectly good, reachable VM in
633	  // ERROR forever (every retry hit the same wall). So skip the start when the VM is
634	  // already running, and treat an "already running" race as success rather than fatal.
635	  const alreadyRunning = await conn
636	    .vmStatus(vmid)
637	    .then((s: { status?: string } | null) => s?.status === "running")
638	    .catch(() => false);
639	  if (!alreadyRunning) {
640	    await step("Starting your server…");
641	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
642	    try {
643	      await conn.waitForTask(startUpid);
644	    } catch (e) {
645	      if (!/already running/i.test(String((e as { message?: unknown })?.message ?? ""))) throw e;
646	    }
647	  }
648	
649	  // `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
650	  // agent whether the machine actually booted before calling it ready (M7 #10).
651	  // A false here is reported, never downgraded into silence.
652	  if (!SANDBOX) await step("Booting the operating system…");
653	  const booted = SANDBOX ? true : await waitForGuestAgent(conn, conn.node, vmid);
654	
655	  // Real end-to-end reachability check — the guest agent above proves only that
656	  // QEMU's in-guest daemon answered (and plenty of images don't even ship it, see
657	  // the `booted` caveat below). Neither that nor `waitForTask` proves a customer
658	  // can actually reach the thing we are about to call "ready". Two real incidents
659	  // shipped without this: a VM whose IP collided with unrelated infrastructure
660	  // (nothing was ever reachable), and separately every game family's
661	  // `docker run -d` setup script creates no systemd unit, so the game process can
662	  // silently fail to start while the container still shows "Up" (confirmed:
663	  // Terraria hung on an interactive world-selection prompt with no TTY, port
664	  // never bound) — PROVISION reported success both times. This throws on
665	  // failure, same as every other fatal step above: the existing `runJob` catch
666	  // path (retry while attempts remain, else ERROR + release the dedicated IP +
667	  // `notifyProvisionFailed`) handles it, and because this runs BEFORE the
668	  // status flip to RUNNING and the deployment email below, neither ever fires
669	  // for a server that failed this check.
670	  if (!SANDBOX) {
671	    // Same address a customer would use: the dedicated IP if one was allocated,
672	    // else the NAT host's public IP + this server's assigned SSH port — reusing
673	    // `dedicated`/`sshPort` computed earlier rather than recomputing them (see
674	    // the identical `sshLine` construction below).
675	    const sshHost = dedicated ? dedicated.address : (server.node?.publicIp ?? process.env.PUBLIC_IP);
676	    const sshCheckPort = dedicated ? 22 : (sshPort ?? 22);
677	    await step("Waiting for network access…");
678	    const ssh = await checkSshReachable(sshHost!, sshCheckPort);
679	    if (!ssh.ok) {
680	      throw new Error(
681	        `SSH did not respond on ${sshHost}:${sshCheckPort} after ~${Math.round(ssh.elapsedMs / 1000)}s ` +
682	          `(${ssh.attempts} attempt(s); last error: ${ssh.error}). The VM started, but nothing answered SSH, ` +
683	          `so this server cannot be handed to the customer as ready.`
684	      );
685	    }
686	
687	    const game = gamePortForServer(server as unknown as ServerFamilyLike);
688	    if (game) {
689	      // The one genuinely game-specific checkpoint: the guest is up and SSH
690	      // answers, but the game process itself may still be pulling its image and
691	      // starting its container before its own port opens — a real, observable
692	      // distinction (not present at all for a plain VPS order), unlike "pulling
693	      // the image" itself, which happens inside the guest's own cloud-init run
694	      // with no channel back to this worker to report on.
695	      await step("Starting the game server…");
696	      // `ip` is the dedicated public IP or the NAT server's private address —
697	      // already computed above. Checking against `ip` proves what this check
698	      // exists to prove: the game process itself bound its port, independent of
699	      // whether that port has been forwarded to the internet yet.
700	      const gameCheck = await checkGamePortOpen(ip, game.port, game.protocol);
701	      if (!gameCheck.ok) {
702	        throw new Error(
703	          `game port ${game.port}/${game.protocol} never opened on ${ip} after ` +
704	            `~${Math.round(gameCheck.elapsedMs / 1000)}s (${gameCheck.attempts} attempt(s); last error: ` +
705	            `${gameCheck.error}). SSH is up, but the game server itself never started listening, so this ` +
706	            `server cannot be handed to the customer as ready.`
707	        );
708	      }
709	      // Auto-forward the game's own port for NAT (non-dedicated-IP) servers, so
710	      // every game server is reachable the moment it's handed to the customer —
711	      // "plug and play" — instead of requiring a manual PortForward from the
712	      // dashboard first. Found live: a real paying Minecraft customer with no
713	      // dedicated IP and zero forwards had no path from any public IP to their
714	      // game port at all. Dedicated IP servers need no forward — their guest
715	      // port already IS the public port.
716	      if (!SANDBOX && !dedicated) {
717	        try {
718	          await allocateGameForward(server.nodeId, server.id, game.port, game.protocol);
719	          const natErr = await syncPortForwardsBestEffort(`provision ${server.hostname} (game port)`);
720	          if (natErr) console.error(`[worker] game port forward sync failed for ${server.hostname}`, natErr);
721	        } catch (e) {
722	          // Never fail the whole provision over this — the server is still usable
723	          // via the dashboard's existing manual "Add forward" as a fallback.
724	          console.error(`[worker] auto-forward game port failed for ${server.hostname}`, e);
725	        }
726	      }
727	      // Minecraft subdomain DNS (lib/game-subdomain-dns.ts): the game port is
728	      // now reachable either way (dedicated IP directly, or the forward just
729	      // created above), so this can fire unconditionally.

800	    body,
801	    `/dashboard/servers/${server.id}`
802	  );
803	  // Post-purchase review request (once per server, skipped if no profiles set).
804	  await sendReviewRequestForServer(server.id);
805	}
