816	  const { conn } = await nodeFor(server);
817	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
818	  await conn.waitForTask(upid);
819	  await db.server.update({
820	    where: { id: server.id },
821	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
