825	/**
826	 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
827	 * lib/proxmox.ts for the incident and the ladder. The bare version of this
828	 * function threw on an already-absent VM, which is what made a retried REINSTALL
829	 * destroy a customer's server permanently.
830	 */
831	async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
832	  const host: VmDestroyHost = {
833	    probe: async (id) => {
834	      try {
835	        await conn.vmStatus(id);
836	        return "present";
837	      } catch (e) {
838	        // Only a vmid-anchored "config does not exist" proves absence. Anything
839	        // else (auth, network, a locked node) is genuinely unknown and must not
840	        // be read as "already gone".
841	        return isVmAbsentError(e, id) ? "absent" : "unknown";
842	      }
843	    },
844	    stop: async (id) => {
845	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
846	      await conn.waitForTask(stopUpid);
847	    },
848	    destroy: async (id) => {
849	      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
850	        "destroy-unreferenced-disks": 1,
851	        purge: 1,
852	      });
853	      await conn.waitForTask(delUpid, 600_000);
854	    },
855	  };
856	  return destroyVmIdempotent(host, vmid);
857	}
