859	async function remove(job: Job) {
860	  const server = await loadServer(job);
861	  const { conn } = await nodeFor(server);
862	  if (!SANDBOX && server.vmid) {
863	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
864	    // so the absent case no longer needs to be caught here at all. The catch that
865	    // remains is narrowed to this vmid: it used to swallow any error containing
866	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
867	    // `volume ... does not exist` — errors that mean the VM is very much still
868	    // running. On one of those the handler proceeded to delete the Server row and
869	    // every Volume row pinned to it, leaving a live VM with no database record:
870	    // invisible to billing, invisible to the panel, still holding the customer's
871	    // data and impossible to reach through any surface we own.
872	    try {
873	      await destroyVm(conn, server.vmid);
874	    } catch (e: any) {
875	      if (!isVmAbsentError(e, server.vmid)) throw e;
876	    }
877	    // Best-effort: remove the per-server cloud-init snippet
878	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
879	  }
880	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
881	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
882	  // Minecraft subdomain DNS (lib/game-subdomain-dns.ts): must clean up here,
883	  // BEFORE the row is deleted below — syncGameServerDns needs the row to still
884	  // exist to read `subdomain` off it.
885	  if (!SANDBOX && server.subdomain) await deleteMinecraftSubdomainDns(server.subdomain).catch((e) => console.error("[worker] delete game subdomain DNS failed", e));
886	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
887	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
888	  // diskName and keep billing forever. Remove them and notify the owner. (The
889	  // reinstall guard already blocks the accidental case; a full server delete is an
890	  // intentional teardown, so we drop the volumes with it.)
891	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
892	  if (orphanVolumes.length > 0) {
893	    await db.volume.deleteMany({ where: { serverId: server.id } });
894	    for (const v of orphanVolumes) {
895	      await notify(
896	        v.userId,
897	        `Volume "${v.name}" was removed`,
898	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
899	        "/dashboard/volumes",
900	      ).catch(() => {});
901	    }
902	  }
903	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
904	  // server.delete cascade removes THIS running Job row — the success-path
905	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
906	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
907	  await db.server.delete({ where: { id: server.id } });
908	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
909	  // DELETE, which then dies on "Server not found" and the sync is never retried
910	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
911	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
912	}
