server {
    listen 80;
    listen [::]:80;
    server_name staging.nxeon.cloud staging.revsports.ca;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$host$request_uri; }
}
# Primary: staging.nxeon.cloud
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name staging.nxeon.cloud;
    ssl_certificate /etc/letsencrypt/live/staging.nxeon.cloud/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/staging.nxeon.cloud/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    client_max_body_size 20m;
    error_page 502 503 504 /maintenance.html;
    location = /maintenance.html {
        root /opt/nxeon-staging/public;
        internal;
