3	# /etc/nxeon/domains.env. This is the ONLY place the domain lives at the ops layer.
4	# Migrate to a new domain: edit /etc/nxeon/domains.env, re-run this script.
5	set -euo pipefail
6	
7	CONF=/etc/nxeon/domains.env
8	[ -f "$CONF" ] || { echo "Missing $CONF"; exit 1; }
9	# shellcheck disable=SC1090
10	. "$CONF"
11	: "${BASE_DOMAIN:?}" "${ADMIN_HOST:?}" "${STAGING_HOST:?}" "${CERTBOT_EMAIL:?}"
12	
13	WWW="www.${BASE_DOMAIN}"
14	PROD_HOSTS=("$BASE_DOMAIN" "$WWW" "$ADMIN_HOST")
15	ALL_HOSTS=("$BASE_DOMAIN" "$WWW" "$ADMIN_HOST" "$STAGING_HOST")
16	
17	# Reusable proxy block
18	proxy_block() {
19	  local upstream="$1"
20	  cat <<EOF
21	        proxy_pass http://127.0.0.1:${upstream};
22	        proxy_http_version 1.1;
23	        proxy_set_header Host \$host;
24	        proxy_set_header X-Real-IP \$remote_addr;
25	        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
26	        proxy_set_header X-Forwarded-Proto \$scheme;
27	        proxy_set_header Upgrade \$http_upgrade;
28	        proxy_set_header Connection "upgrade";
29	EOF
30	}
31	
32	echo "==> Phase 1: HTTP-only vhosts (so certbot can solve the ACME challenge)"
33	mkdir -p /var/www/certbot
34	
35	# Production vhost: customer domain (admin hidden) + admin subdomain
36	cat > /etc/nginx/sites-available/nxeon <<EOF
37	# AUTO-GENERATED by configure-domains.sh — edit /etc/nxeon/domains.env instead.
38	
39	# Customer portal — ${BASE_DOMAIN}
40	server {
41	    listen 80;
42	    listen [::]:80;
43	    server_name ${BASE_DOMAIN} ${WWW};
44	    client_max_body_size 20m;
45	    location /.well-known/acme-challenge/ { root /var/www/certbot; }
46	    # Admin is not exposed on the public domain
47	    location /admin { return 404; }
48	    location / {
49	$(proxy_block 3000)
50	    }
51	}
52	
53	# Admin ops portal — ${ADMIN_HOST}
54	server {
55	    listen 80;
56	    listen [::]:80;
57	    server_name ${ADMIN_HOST};
58	    client_max_body_size 20m;
59	    location /.well-known/acme-challenge/ { root /var/www/certbot; }
60	    location = / { return 302 /admin; }
61	    location / {
62	$(proxy_block 3000)
63	    }
64	}
65	
66	# Default (bare IP / unknown host) → customer portal, admin hidden
67	server {
68	    listen 80 default_server;
69	    listen [::]:80 default_server;
70	    server_name _;
71	    client_max_body_size 20m;
72	    location /.well-known/acme-challenge/ { root /var/www/certbot; }
73	    location /admin { return 404; }
74	    location / {
75	$(proxy_block 3000)
76	    }
77	}
78	EOF
79	
